html:
{#- Controlled copy of a document revision (module 30; URS-QMS-008, URS-CMP-003). -#}
{%- set controlled = doc.status == "Effective" -%}
{%- set document = frappe.db.get_value("Controlled Document", doc.controlled_document, ["title", "department", "next_review_date"], as_dict=True) -%}
<style>
	.mds-copy { font-size: 11px; }
	.mds-copy .mds-banner { padding: 6px 10px; border: 2px solid; font-weight: bold; margin-bottom: 12px; }
	.mds-copy .mds-controlled { border-color: #1a7f37; color: #1a7f37; }
	.mds-copy .mds-uncontrolled { border-color: #b42318; color: #b42318; }
	.mds-copy table { width: 100%; border-collapse: collapse; margin-bottom: 12px; }
	.mds-copy th, .mds-copy td { border: 1px solid #c8c8c8; padding: 4px 6px; text-align: left; vertical-align: top; }
	.mds-copy th { width: 28%; background: #f4f4f4; }
	.mds-copy .mds-hash { font-family: monospace; word-break: break-all; }
</style>
<div class="mds-copy">
	{%- if controlled %}
	<div class="mds-banner mds-controlled">
		{{ _("CONTROLLED COPY") }} · {{ _("Printed on {0}. Check the system for the current revision before use.").format(frappe.utils.format_datetime(frappe.utils.now_datetime())) }}
	</div>
	{%- else %}
	<div class="mds-banner mds-uncontrolled">
		{{ _("UNCONTROLLED – NOT FOR USE") }} · {{ _("Status: {0}").format(_(doc.status)) }}{% if doc.superseded_by %} · {{ _("Superseded by {0}").format(doc.superseded_by | e) }}{% endif %}
	</div>
	{%- endif %}
	<h3>{{ doc.controlled_document | e }} · {{ _("Revision") }} {{ doc.revision | e }}</h3>
	<p><strong>{{ (document.title if document else doc.document_title) | e }}</strong></p>
	<table>
		<tr><th>{{ _("Document type") }}</th><td>{{ _(doc.document_type) | e }}</td></tr>
		<tr><th>{{ _("Department") }}</th><td>{{ (document.department if document else "") | e }}</td></tr>
		<tr><th>{{ _("Status") }}</th><td>{{ _(doc.status) | e }}</td></tr>
		<tr><th>{{ _("Effective date") }}</th><td>{{ frappe.utils.formatdate(doc.effective_date) if doc.effective_date else "" }}</td></tr>
		<tr><th>{{ _("Next review") }}</th><td>{{ frappe.utils.formatdate(document.next_review_date) if controlled and document and document.next_review_date else "" }}</td></tr>
		<tr><th>{{ _("Summary of change") }}</th><td>{{ (doc.summary_of_change or _("First issue")) | e }}</td></tr>
		<tr><th>{{ _("Document file") }}</th><td>{{ (doc.file or "").split("/")[-1] | e }}</td></tr>
		<tr><th>{{ _("File fingerprint (SHA-256)") }}</th><td class="mds-hash">{{ (doc.file_sha256 or _("Not yet signed by its author")) | e }}</td></tr>
	</table>
	<h4>{{ _("Electronic signatures") }}</h4>
	{%- set signatures = signatures_for_print(doc) %}
	{%- if signatures %}
	<table>
		<tr><th>{{ _("Meaning") }}</th><th>{{ _("Signed by") }}</th><th>{{ _("Date and time") }}</th><th>{{ _("Act and reason") }}</th></tr>
		{%- for s in signatures %}
		<tr>
			<td>{{ _(s.meaning) | e }}</td>
			<td>{{ s.signer_name | e }} ({{ s.signer | e }})</td>
			<td>{{ frappe.utils.format_datetime(s.signed_at) }}</td>
			<td>{{ _(s.action) | e }}{% if s.reason %} · {{ s.reason | e }}{% endif %}</td>
		</tr>
		{%- endfor %}
	</table>
	{%- else %}
	<p>{{ _("Not yet signed.") }}</p>
	{%- endif %}
</div>
